export const MATH_MONEY_NOTES = [{"text":"나. 성취기준","ctrls":[]},{"text":"[초등학교 5~6학년]","ctrls":[]},{"text":"(1) 수와 연산 ","ctrls":[]},{"text":"\u{f02b3} 화폐","ctrls":[]},{"text":"초등학교 5~6학년 ‘화폐’는 실생활에서 지폐를 활용하는 능력을 갖추는 데 중점을 두었다. ‘화폐’ 영역의 내용 요소는 지폐 활용으로, 지폐(천 원, 오천 원, 만 원)의 액면가를 알고 실생활에서 물건 가격에 알맞은 지폐를 지불하여 화폐 활용을 경험하는 데 주안점을 둔다.","ctrls":[]},{"text":"","ctrls":[{"id":"tbl ","rows":1,"cols":1,"cells":[{"col":0,"row":0,"colSpan":1,"rowSpan":1,"paras":[{"text":"[6수학01-09] 지폐(천 원, 오천 원, 만 원)의 액면가를 읽고 크기를 비교한다.","ctrls":[]},{"text":"[6수학01-10] 지폐(천 원, 오천 원, 만 원)를 다른 액면가의 지폐로 교환한다.","ctrls":[]},{"text":"[6수학01-11] 몇천 원짜리 상품과 교환할 수 있는 지폐를 찾는다.","ctrls":[]},{"text":"[6수학01-12] 만 몇천 원짜리 상품과 교환할 수 있는 지폐를 찾는다.","ctrls":[]}]}]}]},{"text":"(가) 성취기준 해설","ctrls":[]},{"text":"[6수학01-09], [6수학01-10] 천 원, 오천 원, 만 원권 지폐의 모양, 크기, 색깔, 그림, 수 등을 살펴보는 활동을 한다. 각 지폐의 액면가를 읽고 쓰며, 천원으로 교환할 수 있는 물건의 양보다 오천 원, 만 원이 더 많다는 것을 경험하게 하여 액면가의 차이를 알게 한다. 이후 지폐를 액면가가 작거나 큰 지폐로 교환하는 활동을 한다. ","ctrls":[]},{"text":"[6수학01-11], [수학01-12] 시장 놀이 등의 활동을 통해 천 원, 오천 원, 만 원의 상품 가격에 알맞은 지폐를 지불하여 물건과 지폐를 교환함으로써 화폐의 가치를 인식하게 한다. 천 원이나 만 원과 같은 지폐의 액면가는 고유 명칭이나 단위로 이해하고 천 원 이상부터 2만 원 미만의 범위에서만 상품 가격을 다룬다.","ctrls":[]},{"text":"(나) 성취기준 적용 시 고려 사항","ctrls":[]},{"text":"장애 정도가 심한 학생의 경우 지폐의 앞 뒷면을 확대한 사진을 살펴보며 각 지폐의 특성 중 색깔이나 그림을 통해 구분하고 액면가에 따라 구입할 수 있는 상품 수나 음식의 양 등을 체험하게 하여 화폐의 가치를 친숙한 경험을 통해 이해할 수 있게 한다.","ctrls":[]}];
export const PE_NOTES = [{"text":"나. 성취기준","ctrls":[]},{"text":"[초등학교 3∼4학년]","ctrls":[]},{"text":"(1) 운동","ctrls":[]},{"text":"초등학교 3~4학년의 ‘운동’ 영역은 초보 형태의 체력 운동과 건강 활동 능력을 갖추는 데 중점을 두어 설정하였다. 이 영역은 체력 운동 경험하기, 신체와 주변 청결 습관 기르기, 안전하게 야외활동하기로 구성된다. 이 활동들은 체력 운동과 건강 활동에 대한 이해를 바탕으로 체력 운동을 경험하고 청결과 안전사고 예방을 실천하며, 체력 운동에 대한 관심, 청결한 습관의 중요성, 야외활동 시 안전 의식을 기르는 데 주안점을 둔다.","ctrls":[]},{"text":"\u{f02b1} 체력 운동 ","ctrls":[]},{"text":"","ctrls":[{"id":"tbl ","rows":1,"cols":1,"cells":[{"col":0,"row":0,"colSpan":1,"rowSpan":1,"paras":[{"text":"[4체육01-01] 체력 운동을 경험하고 운동에 관심을 기울인다.","ctrls":[{"id":"cold","texts":[]}]}]}]}]},{"text":"(가) 성취기준 해설 ","ctrls":[]},{"text":"[4체육01-01] 이 성취기준은 일반적인 체력 운동을 실행하기 전 단계의 학생들이 체력 운동과 관련된 여러 움직임과 활동을 경험할 수 있도록 설정하였다. 신체 부위별 움직임 알기, 물체 들어 올리고 내리기와 당기고 밀기(근력 및 근지구력), 물건 가져오면서 왕복달리기(심폐지구력), 재미있는 동작으로 구성한 스트레칭과 관절 운동(유연성) 등을 다룬다. 초보 형태의 놀이나 활동으로 구성된 체력 운동을 경험하면서 체력을 기르고 체력에 관심을 기울일 수 있도록 한다. ","ctrls":[]},{"text":"(나) 성취기준 적용 시 고려 사항","ctrls":[]},{"text":"체력 운동과 관련된 여러 움직임을 경험하는 과정에서 동작을 정확하게 실시하는 것을 강조해야 하지만 이에 앞서 학생들의 관심과 흥미를 유발할 수 있는 체력 운동 동작을 사용하여 활동 동기를 높이도록 한다. ","ctrls":[]},{"text":"[4체육01-01] 장애 정도가 심한 학생의 움직임을 지도할 때에는 동작 시범과 설명, 그리고 신체적 촉진을 사용하여 최적의 학습이 가능하도록 한다. 뇌병변장애 학생은 관절의 경직도, 근육의 경련, 관절가동범위 등을 유의하고, 스트레칭 동작에서는 신체적으로 교정해 주고 스트레칭의 강도를 교사가 조정하여 실시한다. 시각중복장애 학생의 경우 동작을 그림과 사진으로 제시한 인쇄물 또는 동영상을 확대경으로 확인하거나 교사의 동작을 촉지각하여 학습하도록 한다. ","ctrls":[]}];
export const HEALTHY_LIVING_NOTES = [{"text":"나. 성취기준","ctrls":[]},{"text":"건강한 생활과의 성취기준은 통합교과의 4개 영역 간의 중첩을 바탕으로 건강한 몸과 마음을 길러 함께 어울려 살아가는 데 중점을 둔다. 학생은 성취기준을 학습함으로써 몸의 움직임을 자유롭게 경험하며 흥미를 느끼고, 자발적으로 놀이에 참여하며 친구들과 즐겁게 어울려 소통할 수 있다. 또한 규칙을 지키며 다양한 신체 활동과 놀이에 꾸준히 참여함으로써 체력을 기르며 건강하고 안전하게 살아가게 된다.","ctrls":[]},{"text":"이를 위해 바른 생활과, 슬기로운 생활과, 즐거운 생활과의 성취기준과 수평적 연계성을 바탕으로 상호 보완적 성격을 지니는 동시에 교과 교육과정을 구성하는 4개 영역을 중첩하여 언제, 어디서, 무엇에 바탕을 둔 3차원적 주제로 구성하여 학생이 사실적이고 역동적인 삶으로서의 생활 주제를 경험하도록 한다. 그리고 각 성취기준은 ‘지식⋅이해’, ‘과정⋅기능’, ‘가치⋅태도’의 3개 범주의 내용 요소를 균형 있게 구성하여 학생의 전인적 성장을 강조한다.","ctrls":[]},{"text":"","ctrls":[]},{"text":"","ctrls":[{"id":"tbl ","rows":1,"cols":1,"cells":[{"col":0,"row":0,"colSpan":1,"rowSpan":1,"paras":[{"text":"[2건생01-01] 몸의 움직임을 자유롭게 경험한다. ","ctrls":[{"id":"cold","texts":[]}]},{"text":"[2건생01-02] 신체 활동에 꾸준히 참여한다.","ctrls":[]},{"text":"[2건생01-03] 규칙을 지키며 신체 활동에 참여한다.","ctrls":[]},{"text":"[2건생01-04] 놀이를 자발적으로 즐긴다. ","ctrls":[]},{"text":"[2건생01-05] 친구와 함께 즐겁게 어울린다.","ctrls":[]},{"text":"[2건생01-06] 몸을 건강하게 하는 생활 습관을 기른다.","ctrls":[]}]}]}]},{"text":"","ctrls":[{"id":"tbl ","rows":1,"cols":1,"cells":[{"col":0,"row":0,"colSpan":1,"rowSpan":1,"paras":[{"text":"[2건생01-01] 몸의 움직임을 자유롭게 경험한다. ","ctrls":[{"id":"cold","texts":[]}]}]}]}]},{"text":"(가) 성취기준 해설","ctrls":[]},{"text":"성취기준의 설정 취지 및 의미 이 성취기준은 학생이 자기 신체 부위를 자유롭게 움직이고, 움직임의 다양한 방식이나 정도를 경험하며 흥미를 느껴 자기 몸과 움직임에 관심을 가질 수 있도록 설정하였다.","ctrls":[]},{"text":"교수⋅학습의 주안점 비이동 움직임(뻗기, 회전하기, 흔들기, 밀기 등), 이동 움직임(기기, 걷기, 달리기, 구르기 등), 조작 움직임(던지기, 받기, 차기, 치기, 굴리기 등) 등을 포함한다. 이를 위해 움직임을 위한 기능에 익숙해질 수 있도록 다양한 놀이 활동으로 구성하여 반복적으로 경험하게 하고 학생의 자발적인 시도를 격려할 수 있다. ","ctrls":[]},{"text":"(나) 성취기준 적용 시 고려 사항","ctrls":[]},{"text":"장애에 따른 특별한 지원 안내 장애 정도가 심하여 움직임에 제한이 있는 학생의 경우, 관절 가동 범위, 근력, 움직임과 관련된 잔존 기능, 근긴장도 등 신체적 특성을 파악하여 안전하게 활동할 수 있도록 움직임의 유형, 범위, 강도를 조절할 수 있다.","ctrls":[]},{"text":"평가 시 고려 사항 이 성취기준은 학생이 몸을 자발적으로 움직이거나 자유롭게 움직일 수 있는지에 중점을 두어 평가한다. 이를 위해 학생이 스스로 신체를 움직이려는 시도, 가동 범위 내에서의 움직임과 확장, 움직임을 즐기는 태도 등을 확인한다. ","ctrls":[]},{"text":"다른 통합교과 및 범교과와의 연계 안내 바른 생활과의 ‘자기 존중’과 연계해 나의 몸을 움직이며 신체 감각을 발달시켜 자신에게 관심을 가지게 하고, 슬기로운 생활과의 ‘나에 대한 이해’와 연계해 나의 몸을 탐색하고 인식하게 할 수 있다. 또한 즐거운 생활과의 ‘감각’과 연계해 다양한 감각을 느끼고 자연스럽게 몸의 움직임을 경험할 수 있도록 한다. 범교과 학습의 ‘인권 교육’과 연계해 자신과 다른 사람의 몸을 소중하게 여기는 태도를 기를 수 있도록 한다.","ctrls":[]},{"text":"교사 수준의 성취기준 재구성 안내 ‘몸의 움직임’에 ‘과정⋅기능’, ‘가치⋅태도’ 범주의 요소를 조합해 학생에게 적합한 성취기준으로 개발하여 사용할 수 있다. 예를 들어, ‘몸의 움직임을 자발적으로 즐긴다’, ‘몸의 움직임에 즐겁게 참여한다’, ‘몸의 움직임을 꾸준히 즐긴다’ 등과 같이 성취기준을 재구성하여 사용할 수 있다.","ctrls":[]},{"text":"","ctrls":[]},{"text":"","ctrls":[{"id":"tbl ","rows":1,"cols":1,"cells":[{"col":0,"row":0,"colSpan":1,"rowSpan":1,"paras":[{"text":"[2건생01-02] 신체 활동에 꾸준히 참여한다.","ctrls":[{"id":"cold","texts":[]}]}]}]}]},{"text":"(가) 성취기준 해설","ctrls":[]},{"text":"성취기준의 설정 취지 및 의미 이 성취기준은 학생이 흥미와 재미를 느낄 수 있는 기초적인 운동 기능이 포함된 신체 활동을 반복해서 경험하며 익숙해지고, 꾸준히 참여하면서 체력을 기를 수 있도록 설정하였다. ","ctrls":[]},{"text":"교수⋅학습의 주안점 준비 및 정리 운동, 간단한 체조와 율동, 몸으로 하는 표현 활동, 맨손이나 기구를 활용하는 신체 활동, 계절에 따른 신체 활동, 실내⋅외 체육 시설을 이용한 신체 활동 등을 포함한다. 이를 위해 구조화된 신체 활동을 학생의 관심과 선호와 연결하여 반복적으로 경험하게 하고, 활동을 변형하거나 확장하여 다양한 신체 활동에 참여할 수 있게 한다.","ctrls":[]},{"text":"(나) 성취기준 적용 시 고려 사항","ctrls":[]},{"text":"장애에 따른 특별한 지원 안내 신체 움직임에 제한이 있는 학생의 경우, 신체 가동 범위를 고려해 활동을 수정하거나 자세 유지⋅지지 기구, 이동 보조기구, 안전 보조기기 등을 사용하여 참여도를 높일 수 있게 한다. 또한 시각장애로 인해 신체 활동에 참여가 어려운 경우, 잔존 시력을 활용하거나 소리 유도기기, 보행 보조기기, 촉각 표시기 등을 활용하여 참여를 유도할 수 있다.","ctrls":[]},{"text":"평가 시 고려 사항 이 성취기준은 학생이 신체 활동에 지속해서 참여하려는 태도에 중점을 두어 평가한다. 이를 위해 신체 활동에 참여하는 모습을 관찰하여 참여 빈도, 적극성, 자발성, 지속성 등과 신체 활동에 대한 긍정적인 인식의 변화를 총체적으로 확인한다.","ctrls":[]},{"text":"다른 통합교과 및 범교과와의 연계 안내 바른 생활과의 ‘자조 기술’과 연계해 신체 활동 후 깨끗하게 씻는 습관을 기를 수 있도록 하며, 슬기로운 생활과의 ‘학교의 모습과 생활’과 연계해 학교의 놀이터, 운동장, 강당 등에서 신체 활동을 즐길 수 있도록 한다. 또한 즐거운 생활과의 ‘관심과 선호’와 연계해 자신이 좋아하는 신체 활동에 필요한 도구를 선택하여 활동에 참여할 수 있게 한다. 범교과 학습의 ‘진로 교육’과 연계해 신체 활동을 하면서 자신의 흥미와 강점을 탐색할 수 있도록 한다.","ctrls":[]},{"text":"교사 수준의 성취기준 재구성 안내 ‘신체 활동’에 ‘과정⋅기능’, ‘가치⋅태도’ 범주의 요소를 조합해 학생에게 적합한 성취기준으로 개발하여 사용할 수 있다. 예를 들어, ‘신체 활동을 자유롭게 즐긴다’, ‘친구와 함께 신체 활동에 즐겁게 어울린다’, ‘신체 활동에 협력하며 참여한다’ 등과 같이 성취기준을 재구성하여 사용할 수 있다.","ctrls":[]}];
